import java.nio.ByteBuffer;

private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        byte b = bb.get(i++);
        if ((b & 0x80) == 0) {
            // 1-byte character
            sb.append((char) b);
        } else if ((b & 0xE0) == 0xC0) {
            // 2-byte character
            if (bb.hasRemaining()) {
                char c = (char) (((b & 0x1F) << 6) + (bb.get(i++) & 0x3F));
                sb.append(c);
            } else {
                break;
            }
        } else if ((b & 0xF0) == 0xE0) {
            // 3-byte character
            if (bb.hasRemaining() >= 2) {
                char c = (char) (((b & 0x0F) << 12) + ((bb.get(i++) & 0x3F) << 6) + (bb.get(i++) & 0x3F));
                sb.append(c);
            } else {
                break;
            }
        } else if ((b & 0xF8) == 0xF0) {
            // 4-byte character
            if (bb.hasRemaining() >= 3) {
                int codePoint = (((b & 0x07) << 18) + ((bb.get(i++) & 0x3F) << 12) + ((bb.get(i++) & 0x3F) << 6) + (bb.get(i++) & 0x3F));
                sb.append(Character.toChars(codePoint));
            } else {
                break;
            }
        } else {
            // Invalid UTF-8 sequence
            break;
        }
    }
    return i;
}

