class BinaryTree<T> {
    private TreeNode<T> rotateRight(TreeNode<T> node) {
        if (node == null || node.left == null) {
            return node;
        }
        TreeNode<T> newRoot = node.left;
        node.left = newRoot.right;
        newRoot.right = node;
        return newRoot;
    }

    public static void main(String[] args) {
        BinaryTree<Integer> tree = new BinaryTree<>();
        TreeNode<Integer> root = new TreeNode<>(10);
        root.left = new TreeNode<>(5);
        root.left.right = new TreeNode<>(7);
        TreeNode<Integer> newRoot = tree.rotateRight(root);
        System.out.println(newRoot.value); // Should print 5
        System.out.println(newRoot.right.value); // Should print 10
        System.out.println(newRoot.right.left.value); // Should print 7
    }
}

