public class TypeResolver {

    private Map<Class<?>, Map<TypeVariable<?>, Type>> typeVariableCache = new HashMap<>();
    private boolean cacheEnabled = true;

    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        TypeResolver resolver = new TypeResolver();
        return resolver.resolveRawArguments(genericType, targetType);
    }

    private Class<?>[] resolveRawArguments(Type genericType, Class<?> targetType) {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }

        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] result = new Class<?>[actualTypeArguments.length];

        Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap(targetType);
        for (int i = 0; i < actualTypeArguments.length; i++) {
            result[i] = resolveRawClass(actualTypeArguments[i], typeVariableMap);
        }

        return result;
    }

    private Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> targetType) {
        if (cacheEnabled && typeVariableCache.containsKey(targetType)) {
            return typeVariableCache.get(targetType);
        }

        Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
        buildTypeVariableMap(targetType, typeVariableMap);

        if (cacheEnabled) {
            typeVariableCache.put(targetType, typeVariableMap);
        }

        return typeVariableMap;
    }

    private void buildTypeVariableMap(Class<?> targetType, Map<TypeVariable<?>, Type> typeVariableMap) {
        if (targetType.getSuperclass() != null) {
            buildTypeVariableMap(targetType.getSuperclass(), typeVariableMap);
        }

        for (Type type : targetType.getGenericInterfaces()) {
            if (type instanceof ParameterizedType) {
                ParameterizedType parameterizedType = (ParameterizedType) type;
                Class<?> rawType = (Class<?>) parameterizedType.getRawType();
                buildTypeVariableMap(rawType, typeVariableMap);
                buildTypeVariableMap(parameterizedType, typeVariableMap);
            }
        }

        for (TypeVariable<?> typeVariable : targetType.getTypeParameters()) {
            typeVariableMap.put(typeVariable, typeVariable);
