import java.util.Arrays;

public class ByteArrayComparator {
    private byte[] internalArray;

    public ByteArrayComparator(byte[] internalArray) {
        this.internalArray = internalArray;
    }

    public boolean equals(final byte[] data, int offset, final int len) {
        if (data == null || offset < 0 || len < 0 || offset + len > data.length) {
            return false;
        }
        if (internalArray == null) {
            return len == 0;
        }
        if (internalArray.length != len) {
            return false;
        }
        for (int i = 0; i < len; i++) {
            if (internalArray[i] != data[offset + i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        ByteArrayComparator comparator = new ByteArrayComparator(new byte[]{1, 2, 3});
        System.out.println(comparator.equals(new byte[]{1, 2, 3}, 0, 3)); // true
        System.out.println(comparator.equals(new byte[]{1, 2, 3, 4}, 1, 3)); // true
        System.out.println(comparator.equals(new byte[]{1, 2, 4}, 0, 3)); // false
    }
}

