import java.util.Arrays;

public class ArrayUtils {
    public static final Boolean[] EMPTY_BOOLEAN_ARRAY = new Boolean[0];

    /**
     * <p>Defensive programming technique to change a <code>null</code> reference to an empty one.</p> 
     * <p>This method returns an empty array for a <code>null</code> input array.</p> 
     * <p>As a memory optimizing technique an empty array passed in will be overridden with the empty <code>public static</code> references in this class.</p>
     * @param array  the array to check for <code>null</code> or empty
     * @return the same array, <code>public static</code> empty array if <code>null</code> or empty input
     * @since 2.5
     */
    public static Boolean[] nullToEmpty(final Boolean[] array) {
        if (array == null || array.length == 0) {
            return EMPTY_BOOLEAN_ARRAY;
        }
        return array;
    }

    public static void main(String[] args) {
        Boolean[] testArray = null;
        Boolean[] resultArray = nullToEmpty(testArray);
        System.out.println("Resulting array length: " + resultArray.length); // Should print 0

        Boolean[] emptyArray = {};
        resultArray = nullToEmpty(emptyArray);
        System.out.println("Resulting array length: " + resultArray.length); // Should print 0

        Boolean[] nonEmptyArray = {true, false};
        resultArray = nullToEmpty(nonEmptyArray);
        System.out.println("Resulting array length: " + resultArray.length); // Should print 2
    }
}

