import java.util.Properties;

public class PropertyFinder {
    public static String findAndSubst(String key, Properties props) {
        String value = props.getProperty(key);
        if (value != null) {
            value = substituteVars(value, props);
        }
        return value;
    }

    private static String substituteVars(String value, Properties props) {
        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < value.length()) {
            int startIndex = value.indexOf("${", i);
            if (startIndex == -1) {
                result.append(value.substring(i));
                break;
            }
            result.append(value.substring(i, startIndex));
            int endIndex = value.indexOf('}', startIndex + 2);
            if (endIndex == -1) {
                result.append(value.substring(startIndex));
                break;
            }
            String varName = value.substring(startIndex + 2, endIndex);
            String varValue = props.getProperty(varName);
            if (varValue != null) {
                result.append(varValue);
            } else {
                result.append("${").append(varName).append("}");
            }
            i = endIndex + 1;
        }
        return result.toString();
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("greeting", "Hello, ${name}!");
        props.setProperty("name", "World");
        System.out.println(findAndSubst("greeting", props));
    }
}

