import java.io.IOException;
import java.io.InputStream;

public class VarintReader {
    private InputStream input;

    public VarintReader(InputStream input) {
        this.input = input;
    }

    public long readRawVarint64() throws IOException {
        long result = 0;
        for (int shift = 0; shift < 64; shift += 7) {
            int b = input.read();
            if (b == -1) {
                throw new IOException("Unexpected end of input");
            }
            result |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                return result;
            }
        }
        throw new IOException("Malformed Varint");
    }

    public static void main(String[] args) {
        // Example usage
        byte[] data = {0x96, 0x01}; // Represents the number 150 in Varint encoding
        InputStream inputStream = new java.io.ByteArrayInputStream(data);
        VarintReader reader = new VarintReader(inputStream);
        try {
            long value = reader.readRawVarint64();
            System.out.println("Read Varint value: " + value);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

