import org.apache.commons.lang3.tuple.Pair;
import org.apache.commons.math3.geometry.euclidean.twod.Box2D;
import org.apache.commons.math3.geometry.euclidean.twod.Vector2D;

public class BoxSplitter {

    /**
     * Split a box along the x axis into two equal boxes.
     * @param box the box to split
     * @return a pair with the two resulting boxes
     */
    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
        double[] boxBounds = box.getBounds();
        double x1 = boxBounds[0];
        double y1 = boxBounds[1];
        double x2 = boxBounds[2];
        double y2 = boxBounds[3];
        double midX = (x1 + x2) / 2.0;

        Box2D leftBox = new Box2D(new Vector2D(x1, y1), new Vector2D(midX, y2));
        Box2D rightBox = new Box2D(new Vector2D(midX, y1), new Vector2D(x2, y2));

        return Pair.of(leftBox, rightBox);
    }

