public class StringUtils {
    /** 
     * Trim trailing whitespace from the given String.
     * @param str the String to check
     * @return the trimmed String
     * @see java.lang.Character#isWhitespace
     */
    public static String trimTrailingWhitespace(String str) {
        if (str == null || str.isEmpty()) {
            return str;
        }
        int endIndex = str.length() - 1;
        while (endIndex >= 0 && Character.isWhitespace(str.charAt(endIndex))) {
            endIndex--;
        }
        return str.substring(0, endIndex + 1);
    }

    public static void main(String[] args) {
        System.out.println(trimTrailingWhitespace("Hello World   ")); // Should print "Hello World"
        System.out.println(trimTrailingWhitespace("   ")); // Should print ""
        System.out.println(trimTrailingWhitespace("NoTrailingSpace")); // Should print "NoTrailingSpace"
        System.out.println(trimTrailingWhitespace("")); // Should print ""
        System.out.println(trimTrailingWhitespace(null)); // Should print null
    }
}

