import javax.swing.tree.DefaultMutableTreeNode;
import javax.swing.tree.TreeNode;

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int removedCount = 0;
    List<TreeNode> nodesToRemove = new ArrayList<>();
    traverseTree(root, nodesToRemove);
    for (TreeNode node : nodesToRemove) {
        DefaultMutableTreeNode parent = (DefaultMutableTreeNode) node.getParent();
        if (parent != null) {
            parent.remove(node);
            removedCount++;
        }
    }
    return removedCount;
}

private void traverseTree(TreeNode node, List<TreeNode> nodesToRemove) {
    if (node instanceof DefaultMutableTreeNode) {
        DefaultMutableTreeNode mutableNode = (DefaultMutableTreeNode) node;
        if (!mutableNode.isLeaf() && mutableNode.getChildCount() == 0) {
            nodesToRemove.add(node);
        } else {
            for (int i = 0; i < node.getChildCount(); i++) {
                traverseTree(node.getChildAt(i), nodesToRemove);
            }
        }
    }
}

