import java.io.DataInputStream;
import java.io.IOException;

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    byte[] classFileBuffer = {/* This array should be initialized with the actual class file data */};
    try (DataInputStream dataInputStream = new DataInputStream(new ByteArrayInputStream(classFileBuffer))) {
        // Skip to the start of the constant pool
        dataInputStream.skipBytes(8); // Magic, Major and Minor version

        int constantPoolCount = dataInputStream.readUnsignedShort();
        int currentIndex = 1;
        while (currentIndex < constantPoolEntryIndex) {
            int tag = dataInputStream.readUnsignedByte();
            switch (tag) {
                case 1: // CONSTANT_Utf8
                    int length = dataInputStream.readUnsignedShort();
                    dataInputStream.readFully(charBuffer, 0, length);
                    currentIndex++;
                    break;
                case 3: // CONSTANT_Integer
                case 4: // CONSTANT_Float
                    dataInputStream.skipBytes(4);
                    currentIndex++;
                    break;
                case 5: // CONSTANT_Long
                case 6: // CONSTANT_Double
                    dataInputStream.skipBytes(8);
                    currentIndex += 2;
                    break;
                case 7: // CONSTANT_Class
                case 8: // CONSTANT_String
                case 16: // CONSTANT_MethodType
                    dataInputStream.skipBytes(2);
                    currentIndex++;
                    break;
                case 9: // CONSTANT_Fieldref
                case 10: // CONSTANT_Methodref
                case 11: // CONSTANT_InterfaceMethodref
                case 12: // CONSTANT_NameAndType
                case 18: // CONSTANT_InvokeDynamic
                    dataInputStream.skipBytes(4);
                    currentIndex++;
                    break;
                default:
                    throw new IOException("Unknown tag");
            }
        }

        if (currentIndex != constantPoolEntryIndex) {
            throw new IOException("Constant pool entry index not found");
        }

        int length = dataInputStream.readUnsignedShort();
        dataInputStream.readFully(charBuffer, 0, length);
        return new String(charBuffer, 0, length);
    } catch (IOException e) {
        e.printStackTrace();
        return null;
    }
}

