        StringBuilder regex = new StringBuilder();
        int varIndex = 0;
        int start = 0;
        while (start < template.length()) {
            int openIndex = template.indexOf("{", start);
            if (openIndex == -1) {
                regex.append(Pattern.quote(template.substring(start)));
                break;
            }
            regex.append(Pattern.quote(template.substring(start, openIndex)));
            int closeIndex = template.indexOf("}", openIndex);
            if (closeIndex == -1) {
                throw new IllegalArgumentException("Unmatched { in URI template: " + template);
            }
            String varName = template.substring(openIndex + 1, closeIndex);
            variableNames.add(varName);
            regex.append("([^/]+)");
            start = closeIndex + 1;
        }
        return Pattern.compile(regex.toString());
    }

