    public double vertexWeight(V v) {
        double sum = 0.0;
        for (Map.Entry<E, Double> entry : edgeWeights.entrySet()) {
            E edge = entry.getKey();
            Double weight = entry.getValue();
            // Assuming E is a type that has methods from() and to() to get the vertices of the edge
