public class LinkedListImpl<E> {
    private ListNodeImpl<E> first;
    private ListNodeImpl<E> last;
    private int size;

    private boolean unlink(ListNodeImpl<E> node) {
        if (node == null) {
            return false;
        }

        ListNodeImpl<E> next = node.next;
        ListNodeImpl<E> prev = node.prev;

        if (prev == null) {
            first = next;
        } else {
            prev.next = next;
            node.prev = null;
        }

        if (next == null) {
            last = prev;
        } else {
            next.prev = prev;
            node.next = null;
        }

        node.data = null;
        size--;
        return true;
    }

    // Additional methods to make the class functional, not required for the unlink method
    public void add(E element) {
        final ListNodeImpl<E> l = last;
        final ListNodeImpl<E> newNode = new ListNodeImpl<>(l, element, null);
        last = newNode;
        if (l == null) {
            first = newNode;
        } else {
            l.next = newNode;
        }
        size++;
    }

    public int size() {
        return size;
    }
}

