public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int lastDotIndex = path.lastIndexOf('.');
    int lastSeparatorIndex = path.lastIndexOf('/');
    int lastWindowsSeparatorIndex = path.lastIndexOf('\\');
    int lastSeparator = Math.max(lastSeparatorIndex, lastWindowsSeparatorIndex);
    if (lastDotIndex > lastSeparator) {
        return path.substring(0, lastDotIndex);
    } else {
        return path;
    }
}

