public class TokenParser {
    private int pos = 0;
    private int len;
    private boolean lowerCaseNames;
    private int i1;
    private int i2;
    private char[] chars;
    private boolean hasChar;

    public TokenParser(char[] chars, int len) {
        this.chars = chars;
        this.len = len;
    }

    private boolean hasChar() {
        return pos < len;
    }

    private String getToken(boolean lowerCase) {
        String token = new String(chars, i1, i2 - i1);
        return lowerCase ? token.toLowerCase() : token;
    }

    private boolean isOneOf(char ch, char[] options) {
        for (char option : options) {
            if (ch == option) {
                return true;
            }
        }
        return false;
    }

    private String parseToken(final char[] terminators) {
        i1 = pos;
        i2 = pos;
        while (hasChar()) {
            char loc0 = chars[pos];
            if (isOneOf(loc0, terminators)) {
                break;
            }
            i2++;
            pos++;
        }
        return getToken(false);
    }

    public static void main(String[] args) {
        char[] input = "Hello, world!".toCharArray();
        TokenParser parser = new TokenParser(input, input.length);
        char[] terminators = {',', '!'};

        List<String> tokens = new ArrayList<>();
        while (parser.hasChar()) {
            String token = parser.parseToken(terminators);
            if (!token.isEmpty()) {
                tokens.add(token);
            }
            parser.pos++; // Move past the terminator
        }

        for (String token : tokens) {
            System.out.println(token);
        }
    }
}

