import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[10]; // initial capacity
        this.length = 0;
    }

    public ByteVector putInt(final int intValue) {
        int requiredSize = length + 4;
        if (requiredSize > data.length) {
            enlarge(requiredSize);
        }
        data[length++] = (byte) (intValue >>> 24);
        data[length++] = (byte) (intValue >>> 16);
        data[length++] = (byte) (intValue >>> 8);
        data[length++] = (byte) intValue;
        return this;
    }

    private void enlarge(int minCapacity) {
        int oldCapacity = data.length;
        int newCapacity = Math.max(oldCapacity << 1, minCapacity);
        data = Arrays.copyOf(data, newCapacity);
    }

    public static void main(String[] args) {
        ByteVector vector = new ByteVector();
        vector.putInt(123456789);
        System.out.println(Arrays.toString(vector.data));
    }
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    if (a == null || b == null) {
        return a == b;
    }
    if (a.length < count || b.length < count) {
        return false;
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

