import java.util.Stack;

private void pop(final String descriptor) {
    Stack<String> outputFrameStack = new Stack<>();
    if (descriptor.startsWith("(")) {
        int i = 1;
        while (descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            switch (c) {
                case 'B':
                case 'C':
                case 'D':
                case 'F':
                case 'I':
                case 'J':
                case 'S':
                case 'Z':
                case 'L':
                    i++;
                    if (c == 'L') {
                        while (descriptor.charAt(i) != ';') {
                            i++;
                        }
                    }
                    outputFrameStack.pop();
                    break;
                case '[':
                    while (descriptor.charAt(i) == '[') {
                        i++;
                    }
                    if (descriptor.charAt(i) == 'L') {
                        while (descriptor.charAt(i) != ';') {
                            i++;
                        }
                    }
                    outputFrameStack.pop();
                    break;
                default:
                    throw new IllegalArgumentException("Unknown type descriptor: " + c);
            }
        }
    } else {
        switch (descriptor) {
            case "B":
            case "C":
            case "D":
            case "F":
            case "I":
            case "J":
            case "S":
            case "Z":
                outputFrameStack.pop();
                break;
            case "L":
                while (descriptor.charAt(descriptor.length() - 1) != ';') {
                    descriptor = descriptor.substring(0, descriptor.length() - 1);
                }
                outputFrameStack.pop();
                break;
            case "[":
                int arrayDepth = 1;
                while (descriptor.charAt(arrayDepth) == '[') {
                    arrayDepth++;
                }
                if (descriptor.charAt(arrayDepth) == 'L') {
                    while (descriptor.charAt(descriptor.length() - 1) != ';') {
                        descriptor = descriptor.substring(0, descriptor.length() - 1);
                    }
                }
                outputFrameStack.pop();
                break;
            default:
                throw new IllegalArgumentException("Unknown type descriptor: " + descriptor);
        }
    }
}

