import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[10];
        this.length = 0;
    }

    public final ByteVector put11(final int byteValue1, final int byteValue2) {
        int loc0 = this.length;
        if (loc0 + 2 > this.data.length) {
            enlarge(2);
        }
        byte[] loc1 = this.data;
        loc1[loc0++] = (byte) byteValue1;
        loc1[loc0++] = (byte) byteValue2;
        this.length = loc0;
        return this;
    }

    private void enlarge(int size) {
        int newCapacity = (this.data.length << 1) + size;
        this.data = Arrays.copyOf(this.data, newCapacity);
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector();
        bv.put11(0x41, 0x42);
        System.out.println(Arrays.copyOf(bv.data, bv.length));
    }
}

